#!/usr/bin/env bash
# Wait for H6 checkpoint-50, then run mid50_early_sim.sh.
# Do NOT edit this file while it is live.
set -euo pipefail
LOG=/root/logs/h6_mid50_wait.nohup
ADAPTER=/root/h6/train/checkpoints/checkpoint-50
SCRIPT=/root/mining_src/s4-h6-talentpigs-shortz-mild/mid50_early_sim.sh
DEADLINE_UTC=${DEADLINE_UTC:-2026-08-07T18:00:00Z}

log() { echo "[h6-mid50-wait] $(date -u +%Y-%m-%dT%H:%M:%SZ) $*" | tee -a "$LOG"; }

mkdir -p /root/logs
: >"$LOG"
log "waiting for $ADAPTER/adapter_config.json"
i=0
while [[ ! -f "$ADAPTER/adapter_config.json" ]]; do
  now=$(date -u +%s)
  dead=$(date -u -d "$DEADLINE_UTC" +%s)
  if (( now > dead )); then
    log "ABORT: deadline without checkpoint-50"
    echo "aborted_no_ckpt50 $(date -u +%Y-%m-%dT%H:%M:%SZ)" \
      >/root/logs/h6_mid50_early.aborted
    exit 1
  fi
  if [[ -f /root/logs/h6_merge.done ]]; then
    log "final merge already done — skip mid50"
    echo "skipped_final_already $(date -u +%Y-%m-%dT%H:%M:%SZ)" \
      >/root/logs/h6_mid50_early.aborted
    exit 0
  fi
  i=$((i + 1))
  if (( i % 6 == 0 )); then
    step=$(grep -oE 'step=[0-9]+' /root/logs/h6_train.nohup 2>/dev/null | tail -1 || true)
    log "still waiting ($step) poll#$i"
  fi
  sleep 10
done
log "checkpoint-50 present — launch mid50_early_sim.sh"
exec bash "$SCRIPT"
